@page "/dashboard"
@using sv_f14249c5dc124b5fbc0f0f1fb2062a79.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<h4 class="text-muted mb-4">@WarehouseState.SelectedWarehouseName</h4>

<div class="row">
    <div class="col-md-4">
        <div class="card border-danger mb-3">
            <div class="card-header bg-danger text-white">
                <strong>Low Stock Alerts</strong>
            </div>
            <div class="card-body text-center">
                <h2 class="card-title display-4">@AlertService.LastLowStockCount</h2>
                <p class="card-text text-muted">items below minimum levels</p>
                <p class="card-text"><small class="text-muted">Last checked: @_lastChecked?.ToString("HH:mm:ss")</small></p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card mb-3">
            <div class="card-header">
                <strong>Polling Status</strong>
            </div>
            <div class="card-body">
                <p>Warehouse: <strong>@WarehouseState.SelectedWarehouseId</strong></p>
                <p>Polling: <span class="badge bg-success">Active</span></p>
                <p>Interval: every 10 seconds</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card mb-3">
            <div class="card-header">
                <strong>Quick Actions</strong>
            </div>
            <div class="card-body">
                <button class="btn btn-outline-primary w-100 mb-2" @onclick="RefreshNow">
                    Refresh Now
                </button>
            </div>
        </div>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private DateTime? _lastChecked;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override async Task OnInitializedAsync()
    {
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        WarehouseState.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        await PollAlerts();
        StartPolling();
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await InvokeAsync(async () =>
                {
                    await PollAlerts();
                });
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task PollAlerts()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.SelectedWarehouseId);
        _lastChecked = DateTime.Now;
        // This notifies ALL subscribers (sidebar badge, this page, etc.)
        AlertService.UpdateAlertCount(count);
    }

    private async Task OnWarehouseChanged()
    {
        // Warehouse changed — poll immediately for the new warehouse
        await PollAlerts();
        StateHasChanged();
    }

    private async Task RefreshNow()
    {
        await PollAlerts();
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

